-- ============================================================================
-- ERP 会计科目：按下载科目表分类整理并覆盖同编码科目（v210）
--
-- 来源：C:/Users/liush/Downloads/会计科目_2026-09-03-15-34-08-666.xlsx
-- 口径：
--   1. 按科目编码首位归类：1资产 / 2负债 / 3共同 / 4权益 / 5成本 / 6损益。
--   2. 使用 INSERT ... ON DUPLICATE KEY UPDATE 覆盖同一 tenant_id=1、deleted=0 下已有科目编码。
--   3. 不清空、不删除、不重建 erp_accounting_subject。
--   4. 不写入 erp_subject_auxiliary；Excel 原辅助核算原文仅写入 remark 便于后续确认。
--   5. 依赖 erp_finance_v29.sql 已为 erp_accounting_subject 增加 voucher_type 字段。
-- ============================================================================


ON DUPLICATE KEY UPDATE
    `subject_name` = VALUES(`subject_name`),
    `short_name` = VALUES(`short_name`),
    `subject_category` = VALUES(`subject_category`),
    `parent_code` = VALUES(`parent_code`),
    `subject_level` = VALUES(`subject_level`),
    `is_leaf` = VALUES(`is_leaf`),
    `balance_direction` = VALUES(`balance_direction`),
    `opening_balance` = VALUES(`opening_balance`),
    `enable` = VALUES(`enable`),
    `sort` = VALUES(`sort`),
    `voucher_type` = VALUES(`voucher_type`),
    `remark` = VALUES(`remark`),
    `updater` = VALUES(`updater`),
    `update_time` = CURRENT_TIMESTAMP;
